package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

final class InboundMailAcceptance {
 static String config(String id){return "/api/openservice/inbound-mailboxes"+(id.isEmpty()?"":"/"+id);}
 static String api(String id){return "/api/openservice/inbound-mail/"+id;}
 static Map<String,Object> settings(int revision,boolean active){return map("revision",revision,"address","help@opensoft.test","sender_domain","example.test","gateway_username","MailGateway","active",active);}
 static String[] setup(WorkflowSupport h)throws Exception {
  String token,gateway,sender,other;try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String name:List.of("MailGateway","MailSender","MailOther","MailAgent","MailReader"))Service.createAccount(db,map("name",name,"password",PASSWORD,"role",name.equals("MailReader")?"reader":Set.of("MailSender","MailOther").contains(name)?"requester":"agent"));gateway=RecordAccess.owner(db,"MailGateway");sender=RecordAccess.owner(db,"MailSender");other=RecordAccess.owner(db,"MailOther");db.update("UPDATE os_user SET api_only=1 WHERE user_id=?",gateway);db.update("UPDATE os_user SET email='sender@example.test',email_verified=1 WHERE user_id=?",sender);db.update("UPDATE os_user SET email='other@example.test',email_verified=1 WHERE user_id=?",other);token=ApiKeyWrites.issue(db,db.viewerId,gateway,map("label","Native mail gateway","table","sc_request","days",1)).get("token").toString();db.connection.commit();}String mailbox=object(result(h.json("POST",config(""),settings(0,true),auth("admin"))).get("mailbox")).get("mailbox_id").toString();return new String[]{mailbox,token,gateway,sender,other};
 }
 static Map<String,Object> message(String delivery,String thread){return map("delivery_id",delivery,"recipient","help@opensoft.test","sender","sender@example.test","sender_verified",true,"subject","Email request <script>","text","Please arrange approved service work <script>","thread_id",thread);}
 static Map<String,Object> submit(WorkflowSupport h,String[] ids,Map<String,Object> body)throws Exception{return result(h.json("POST",api(ids[0]),body,"Bearer "+ids[1]));}
 static void run(WorkflowSupport h)throws Exception {
  var ids=setup(h);var body=message("delivery-1","");var first=submit(h,ids,body);assertEquals(false,first.get("duplicate"));String record=object(first.get("record")).get("sys_id").toString(),thread=first.get("thread_id").toString();assertEquals("Please arrange approved service work <script>",get(h,"/api/now/table/sc_request/"+record,"MailSender").get("description"));assertEquals(404,h.get("/api/now/table/sc_request/"+record,auth("MailOther")).statusCode());var duplicate=submit(h,ids,body);assertEquals(true,duplicate.get("duplicate"));assertEquals(thread,duplicate.get("thread_id"));var changed=new LinkedHashMap<>(body);changed.put("text","Different content");assertEquals(409,h.json("POST",api(ids[0]),changed,"Bearer "+ids[1]).statusCode());var reply=message("delivery-2",thread);reply.put("text","Additional details for this request");assertEquals(record,object(submit(h,ids,reply).get("record")).get("sys_id"));assertEquals(true,submit(h,ids,reply).get("duplicate"));var comments=objects(parsed(h.get("/api/openservice/comments/sc_request/"+record,auth("MailSender"))).get("result"));assertEquals(1,comments.size());assertEquals("MailSender",comments.getFirst().get("actor"));assertEquals("Additional details for this request",object(comments.getFirst().get("detail")).get("body"));assertEquals(2,objects(get(h,config(ids[0]),"admin").get("receipts")).size());new Store(h.environment);assertEquals(true,submit(h,ids,reply).get("duplicate"));result(h.json("PATCH","/api/now/table/sc_request/"+record,map("state","fulfilling"),auth("MailAgent")));var another=message("delivery-3",thread);submit(h,ids,another);result(h.json("PATCH","/api/now/table/sc_request/"+record,map("state","complete"),auth("MailAgent")));assertEquals(409,h.json("POST",api(ids[0]),message("delivery-4",thread),"Bearer "+ids[1]).statusCode());assertEquals(true,submit(h,ids,body).get("duplicate"));assertEquals(204,h.json("DELETE","/api/now/table/sc_request/"+record,map(),auth("admin")).statusCode());assertTrue(object(objects(get(h,config(ids[0]),"admin").get("receipts")).getFirst().get("record")).isEmpty());assertEquals(404,h.json("POST",api(ids[0]),body,"Bearer "+ids[1]).statusCode());
 }
 static void boundaries(WorkflowSupport h)throws Exception {
  var ids=setup(h);assertEquals(401,h.json("POST",api(ids[0]),message("a",""),null).statusCode());assertEquals(403,h.json("POST",api(ids[0]),message("a",""),auth("MailGateway")).statusCode());assertEquals(403,h.get(api(ids[0]),"Bearer "+ids[1]).statusCode());assertEquals(400,h.json("POST",api(ids[0])+"?x=y",message("a",""),"Bearer "+ids[1]).statusCode());assertEquals(403,h.get(config(""),auth("MailAgent")).statusCode());assertEquals(404,h.get(config(Values.id()),auth("admin")).statusCode());assertEquals(400,h.get(config("")+"?x=y",auth("admin")).statusCode());for(var change:List.of(map("extra",1),map("sender_verified",false),map("sender_verified","true"),map("delivery_id","<>"),map("recipient","wrong@opensoft.test"),map("sender","invalid"),map("subject",""),map("text","x".repeat(8001)),map("thread_id",1),map("thread_id","bad"))){var bad=message("invalid","");bad.putAll(change);assertEquals(400,h.json("POST",api(ids[0]),bad,"Bearer "+ids[1]).statusCode());}var bad=message("domain","");bad.put("sender","sender@other.test");assertEquals(403,h.json("POST",api(ids[0]),bad,"Bearer "+ids[1]).statusCode());bad.put("sender","unknown@example.test");assertEquals(403,h.json("POST",api(ids[0]),bad,"Bearer "+ids[1]).statusCode());assertEquals(404,h.json("POST",api(ids[0]),message("unknown-thread",Values.id()),"Bearer "+ids[1]).statusCode());var first=submit(h,ids,message("first",""));var foreign=message("foreign",first.get("thread_id").toString());foreign.put("sender","other@example.test");assertEquals(404,h.json("POST",api(ids[0]),foreign,"Bearer "+ids[1]).statusCode());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_inbound_mail_receipt"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_record WHERE \"table\"='sc_request'"));}
 }
 static void configuration(WorkflowSupport h)throws Exception {
  var ids=setup(h);assertEquals(200,h.get("/api/now/table/sc_request","Bearer "+ids[1]).statusCode());assertEquals(200,h.get(config(""),auth("admin")).statusCode());assertEquals(200,h.get("/admin/inbound-mail/new",auth("admin")).statusCode());for(var change:List.of(map("extra",1),map("active","true"),map("address","bad"),map("sender_domain","bad domain"),map("gateway_username","unknown"))){var bad=settings(1,true);bad.putAll(change);assertEquals(400,h.json("POST",config(ids[0]),bad,auth("admin")).statusCode());}assertEquals(409,h.json("POST",config(ids[0]),settings(99,true),auth("admin")).statusCode());assertEquals(409,h.json("POST",config(""),settings(0,true),auth("admin")).statusCode());var wrong=settings(1,true);wrong.put("gateway_username","MailAgent");assertEquals(409,h.json("POST",config(ids[0]),wrong,auth("admin")).statusCode());var form=settings(1,true);form.put("active","maybe");assertEquals(400,h.protectedForm("/admin/inbound-mail/"+ids[0],form,auth("admin")).statusCode());result(h.json("POST",config(ids[0]),settings(1,false),auth("admin")));assertEquals(403,h.json("POST",api(ids[0]),message("disabled",""),"Bearer "+ids[1]).statusCode());result(h.json("POST",config(ids[0]),settings(2,true),auth("admin")));for(String type:List.of("readonly","wrongtable","wronggateway")){String token;try(var db=h.store.open()){PlatformFoundationTest.bind(db);if(type.equals("wronggateway")){String other=RecordAccess.owner(db,"MailAgent");db.update("UPDATE os_user SET api_only=1 WHERE user_id=?",other);token=ApiKeyWrites.issue(db,db.viewerId,other,map("label","Other gateway","table","sc_request","days",1)).get("token").toString();}else if(type.equals("readonly"))token=ApiKeys.issue(db,db.viewerId,ids[2],map("label","Read only","table","sc_request","days",1)).get("token").toString();else token=ApiKeyWrites.issue(db,db.viewerId,ids[2],map("label","Wrong scope","table","incident","days",1)).get("token").toString();db.connection.commit();}assertEquals(403,h.json("POST",api(ids[0]),message(type,""),"Bearer "+token).statusCode());}try(var db=h.store.open()){db.update("UPDATE os_api_key SET enabled=0 WHERE token_hash=?",Passwords.tokenHash(ids[1]));db.connection.commit();}assertEquals(401,h.json("POST",api(ids[0]),message("revoked",""),"Bearer "+ids[1]).statusCode());try(var db=h.store.open()){db.update("UPDATE os_api_key SET enabled=1 WHERE token_hash=?",Passwords.tokenHash(ids[1]));db.update("UPDATE os_user SET active=0 WHERE user_id=?",ids[2]);db.connection.commit();}assertEquals(401,h.json("POST",api(ids[0]),message("inactive-gateway",""),"Bearer "+ids[1]).statusCode());result(h.json("POST",config(ids[0]),settings(3,false),auth("admin")));assertEquals(0,object(get(h,config(ids[0]),"admin").get("mailbox")).get("active"));try(var db=h.store.open()){for(int n=1;n<100;n++)db.update("INSERT INTO os_inbound_mailbox(mailbox_id,address,sender_domain,gateway_id,active,revision) VALUES(?,?,?,?,0,1)",Values.id(),"capacity-"+n+"@opensoft.test","example.test",ids[2]);db.connection.commit();}var full=settings(0,false);full.put("address","capacity-last@opensoft.test");assertEquals(400,h.json("POST",config(""),full,auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception {
  var ids=setup(h);for(String flag:List.of("active","email_verified","password_reset_required","api_only")){int original=Set.of("active","email_verified").contains(flag)?1:0;try(var db=h.store.open()){db.update("UPDATE os_user SET "+flag+"=? WHERE user_id=?",1-original,ids[3]);db.connection.commit();}try{assertEquals(403,h.json("POST",api(ids[0]),message("flag-"+flag,""),"Bearer "+ids[1]).statusCode());}finally{try(var db=h.store.open()){db.update("UPDATE os_user SET "+flag+"=? WHERE user_id=?",original,ids[3]);db.connection.commit();}}}Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"sc_request");}for(String restriction:List.of("read","create")){var schema=new LinkedHashMap<>(original);schema.put("record_roles",map(restriction,List.of("admin","agent")));ReferencePickerAcceptance.writeSchema(h,"sc_request",schema);try{assertEquals(403,h.json("POST",api(ids[0]),message("policy-"+restriction,""),"Bearer "+ids[1]).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}}for(String field:List.of("description","state")){var schema=new LinkedHashMap<>(original);schema.put("field_rules",map(field,map("type","string","read_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"sc_request",schema);try{assertEquals(403,h.json("POST",api(ids[0]),message("field-"+field,""),"Bearer "+ids[1]).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_inbound_mail_thread"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_record WHERE \"table\"='sc_request'"));}}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}}var first=submit(h,ids,message("first",""));String record=object(first.get("record")).get("sys_id").toString(),thread=first.get("thread_id").toString();var blocked=new LinkedHashMap<>(original);blocked.put("field_rules",map("description",map("type","string","write_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"sc_request",blocked);try{assertEquals(403,h.json("POST",api(ids[0]),message("blocked-comment",thread),"Bearer "+ids[1]).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}var allowed=new LinkedHashMap<>(original);allowed.put("field_rules",map("description",map("type","string","write_roles",List.of("admin","agent","requester"))));ReferencePickerAcceptance.writeSchema(h,"sc_request",allowed);submit(h,ids,message("allowed-comment",thread));ReferencePickerAcceptance.writeSchema(h,"sc_request",original);ProblemInvestigationsAcceptance.access(h,"sc_request",record,"private",ids[4]);assertEquals(404,h.json("POST",api(ids[0]),message("hidden-comment",thread),"Bearer "+ids[1]).statusCode());assertEquals(404,h.json("POST",api(ids[0]),message("first",""),"Bearer "+ids[1]).statusCode());ProblemInvestigationsAcceptance.access(h,"sc_request",record,"workspace","");try(var db=h.store.open()){db.update("UPDATE os_user SET email='changed@example.test' WHERE user_id=?",ids[3]);db.connection.commit();}assertEquals(403,h.json("POST",api(ids[0]),message("email-changed",thread),"Bearer "+ids[1]).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET email='sender@example.test' WHERE user_id=?",ids[4]);db.connection.commit();}assertEquals(409,h.json("POST",api(ids[0]),message("first",""),"Bearer "+ids[1]).statusCode());assertEquals(404,h.json("POST",api(ids[0]),message("new-sender-old-thread",thread),"Bearer "+ids[1]).statusCode());
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  var ids=setup(h);var body=message("parallel","");Map<String,Object> first;try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return submit(h,ids,body);});var b=pool.submit(()->{start.await();return submit(h,ids,body);});start.countDown();first=a.get();var second=b.get();assertEquals(object(first.get("record")).get("sys_id"),object(second.get("record")).get("sys_id"));assertEquals(Set.of(true,false),Set.of(first.get("duplicate"),second.get("duplicate")));}String thread=first.get("thread_id").toString();var reply=message("parallel-reply",thread);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return submit(h,ids,reply).get("duplicate");});var b=pool.submit(()->{start.await();return submit(h,ids,reply).get("duplicate");});start.countDown();assertEquals(Set.of(true,false),Set.of(a.get(),b.get()));}try(var db=h.store.open()){var row=db.one("SELECT * FROM os_inbound_mail_receipt WHERE mailbox_id=? AND delivery_id='parallel'",ids[0]);for(int n=2;n<199;n++)db.update("INSERT INTO os_inbound_mail_receipt(mailbox_id,delivery_id,fingerprint,sender_id,record_id,thread_id,gateway_id,mailbox_revision,created) VALUES(?,?,?,?,?,?,?,?,?)",ids[0],"retained-"+n,row.get("fingerprint"),ids[3],row.get("record_id"),thread,ids[2],1,now());db.connection.commit();}submit(h,ids,message("last-thread-message",thread));assertEquals(400,h.json("POST",api(ids[0]),message("thread-full",thread),"Bearer "+ids[1]).statusCode());try(var db=h.store.open()){var row=db.one("SELECT * FROM os_inbound_mail_receipt WHERE mailbox_id=? AND delivery_id='parallel'",ids[0]);try(var statement=db.connection.prepareStatement("INSERT INTO os_inbound_mail_receipt(mailbox_id,delivery_id,fingerprint,sender_id,record_id,thread_id,gateway_id,mailbox_revision,created) VALUES(?,?,?,?,?,?,?,?,?)")){for(int group=1;group<50;group++){String more=Values.id();db.update("INSERT INTO os_inbound_mail_thread(thread_id,mailbox_id,sender_id,record_id,created) VALUES(?,?,?,?,?)",more,ids[0],ids[3],row.get("record_id"),now());for(int n=0;n<200;n++){Object[] values={ids[0],"capacity-"+group+"-"+n,row.get("fingerprint"),ids[3],row.get("record_id"),more,ids[2],1,now()};for(int k=0;k<values.length;k++)statement.setObject(k+1,values[k]);statement.addBatch();}}statement.executeBatch();}db.connection.commit();}assertEquals(400,h.json("POST",api(ids[0]),message("mailbox-full",""),"Bearer "+ids[1]).statusCode());assertEquals(true,submit(h,ids,body).get("duplicate"));assertEquals(100,objects(get(h,config(ids[0]),"admin").get("receipts")).size());
 }

}
